type NavItem = 'Workspace' | 'Research lab' | 'Mission control' | 'Tools' | 'Market pulse' | 'Listing history' | 'Media studio' | 'Provider center'

const navItems: Array<{ label: NavItem; icon: typeof LayoutDashboard }> = [
  { label: 'Workspace', icon: LayoutDashboard }, { label: 'Research lab', icon: Search }, { label: 'Mission control', icon: Zap },
  { label: 'Tools', icon: BarChart3 }, { label: 'Market pulse', icon: LineChart }, { label: 'Listing history', icon: FileText }, { label: 'Media studio', icon: ImageIcon }, { label: 'Provider center', icon: Network },
]
const evidenceTone: Record<EvidenceState, string> = { verified: 'tone-verified', derived: 'tone-derived', needs_review: 'tone-review', unknown: 'tone-unknown' }
const evidenceText: Record<EvidenceState, string> = { verified: 'Verified', derived: 'Derived', needs_review: 'Needs review', unknown: 'Unknown' }

function StatusPill({ state, children }: { state: 'live' | 'demo' | 'secure' | 'warn' | 'neutral' | 'local'; children: ReactNode }) { return <span className={clsx('status-pill', `status-${state}`)}>{children}</span> }
function EvidenceBadge({ state }: { state: EvidenceState }) { return <span className={clsx('evidence-badge', evidenceTone[state])}>{evidenceText[state]}</span> }
function Card({ children, className = '', noPadding = false }: { children: ReactNode; className?: string; noPadding?: boolean }) { return <section className={clsx('surface-card', noPadding && 'no-padding', className)}>{children}</section> }
function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) { return <div className="section-heading"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h2>{title}</h2></div>{action}</div> }

type CapabilityProvider = { id: string; label: string; category: 'local' | 'public-gradio' | 'official-api' | 'byok-external' | 'browser'; status: 'ready' | 'sleeping' | 'building' | 'unavailable' | 'unsupported' | 'not_configured' | 'degraded' | 'rate_limited' | 'blocked_by_policy'; capabilities: string[]; details: string; provenance?: string; auth?: string; expectedLatency?: string; costClass?: string; configured?: boolean }
type CapabilityResponse = { checkedAt: string; recommendation: { label: string; reason: string }; providers: CapabilityProvider[]; registry?: { providers: CapabilityProvider[]; capabilities: Array<{ id: string; label: string; status: string; providerIds: string[]; details: string }>; checkedAt: string }; policy: { automaticInference?: boolean; externalRequests: string; rateLimitBehavior?: string; credentials?: string } }
function CapabilityPanel({ notify }: { notify: (message: string) => void }) {
  const [checking, setChecking] = useState(false)
  const [response, setResponse] = useState<CapabilityResponse | null>(null)
  const check = () => {
    if (checking) return
    setChecking(true)
    void fetch('/api/capabilities', { headers: { accept: 'application/json' } })
      .then(async (result) => ({ result, payload: await result.json() as CapabilityResponse }))
      .then(({ result, payload }) => {
        if (!result.ok) throw new Error('unavailable')
        setResponse(payload)
        notify('Capability check complete. Local evidence mode remains the default route.')
      })
      .catch(() => notify('Capability discovery is unavailable here. Local evidence mode remains ready.'))
      .finally(() => setChecking(false))
  }
  const fallbackProviders: CapabilityProvider[] = [{ id: 'local-evidence-engine', label: 'Local evidence engine', category: 'local', status: 'ready', capabilities: ['evidence review', 'listing draft', 'draft export'], details: 'Available immediately without external credentials.', provenance: 'AiBay local runtime' }]
  const providers = response?.registry?.providers ?? response?.providers ?? fallbackProviders
  return <Card className="capability-panel"><SectionHeading eyebrow="CAPABILITY ROUTING" title="Choose the honest available route" action={<button className="secondary-button capability-check" onClick={check}>{checking ? <LoaderCircle className="spin" size={15} /> : <RefreshCw size={15} />}{checking ? 'Checking' : 'Check routes'}</button>} /><p className="capability-intro">AiBay starts with local evidence work and selects other providers only when they are configured, healthy, and permitted for the task. No external route is presented as unlimited or automatically trusted.</p><div className="capability-list">{providers.map((provider) => <div className="capability-row" key={provider.id}><span className={clsx('capability-state', `capability-${provider.status}`)}>{provider.status === 'ready' ? <Check size={14} /> : provider.status === 'degraded' || provider.status === 'rate_limited' ? <Clock3 size={14} /> : <Info size={14} />}</span><div><strong>{provider.label}</strong><p>{provider.details}</p><small>{provider.auth ? `${provider.auth} · ` : ''}{provider.expectedLatency ? `${provider.expectedLatency} latency · ` : ''}{provider.capabilities.length ? provider.capabilities.join(' · ') : 'No capability currently available'}</small></div><StatusPill state={provider.status === 'ready' ? 'local' : provider.status === 'unavailable' || provider.status === 'blocked_by_policy' ? 'warn' : 'neutral'}>{provider.status.replace('_', ' ')}</StatusPill></div>)}</div><div className="capability-foot"><ShieldCheck size={15} /><span>{response?.recommendation.reason ?? 'Local evidence engine is available immediately. No external endpoint is selected automatically.'}</span></div></Card> }

type AiRouteStatus = { id: string; label: string; configured: boolean; freeTier: boolean; costClass: string; model: string | null; host: string | null; reason: string }
type AdapterInventoryEntry = { providerId: string; label: string; version: string; contractVersion: string; capabilityIds: string[]; auth: string; costClass: string; health: { status: string; detail: string; version?: string }; limits: { timeoutMs: number; maxRedirects: number; maxBytes: number; maxRetryAttempts: number }; fallbackPriority: string[] }
type ProviderCenterResponse = { status: string; checkedAt: string; providers: CapabilityProvider[]; adapters?: AdapterInventoryEntry[]; aiRoutes?: AiRouteStatus[]; note?: string }
const FREE_ROUTE_GUIDE = [
  { provider: 'Groq', host: 'api.groq.com/openai/v1', model: 'llama-3.3-70b-versatile', tier: 'Free tier', notes: 'OpenAI-compatible; high throughput free tier' },
  { provider: 'Google Gemini', host: 'generativelanguage.googleapis.com/v1beta/openai', model: 'gemini-2.0-flash', tier: 'Free tier', notes: 'OpenAI-compatible endpoint on the free API tier' },
  { provider: 'OpenRouter', host: 'openrouter.ai/api/v1', model: 'meta-llama/llama-3.3-70b-instruct:free', tier: ':free models', notes: 'Free models available; per-model limits apply' },
  { provider: 'Workers AI', host: 'api.cloudflare.com/client/v4/accounts/<id>/ai/v1', model: '@cf/meta/llama-3.1-8b-instruct', tier: 'Cloudflare plan', notes: 'OpenAI-compatible gateway on your own account' },
  { provider: 'Local Ollama', host: 'http://127.0.0.1:11434/v1', model: 'llama3.2', tier: 'Local only', notes: 'Dev-only; server-side, never exposed to clients' },
]
function ProviderCenter({ notify }: { notify: (message: string) => void }) {
  const [checking, setChecking] = useState(false)
  const [data, setData] = useState<ProviderCenterResponse | null>(null)
  const [infra, setInfra] = useState<{ persistence: string; bindings: { d1: string; kv: string; r2: string; queue: string }; cache: { mode: string; durable: boolean }; browserRun: { status: string; detail: string }; workersAi: { configured: boolean } } | null>(null)
  const check = () => {
    if (checking) return
    setChecking(true)
    void Promise.all([
      fetch('/api/providers', { headers: { accept: 'application/json' } }).then(async (response) => ({ response, payload: await response.json() as ProviderCenterResponse })),
      fetch('/api/infra', { headers: { accept: 'application/json' } }).then(async (response) => ({ response, payload: await response.json() as typeof infra })).catch(() => ({ response: null as Response | null, payload: null })),
    ]).then(([providers, infraResult]) => {
      if (!providers.response.ok) throw new Error('unavailable')
      setData(providers.payload)
      if (infraResult.payload) setInfra(infraResult.payload)
      notify('Provider inventory and infrastructure refreshed.')
    })
      .catch(() => notify('Provider inventory is unavailable here. The free engine remains ready.'))
      .finally(() => setChecking(false))
  }
  const engine = data?.adapters?.find((adapter) => adapter.providerId === 'local.evidence')
  const aiRoutes = data?.aiRoutes ?? []
  const cacheMode = infra?.cache.mode ?? 'edge (request-scoped)'
  return <div className="provider-center-page"><div className="page-intro"><p className="eyebrow">PROVIDER CENTER</p><h1>Free engine on. Connect your own free-tier AI routes.</h1><p>AiBay routes AI work across every OpenAI-compatible endpoint you configure — including free tiers — and fails over automatically. Nothing runs without your server-side credential, and no credential ever reaches this page.</p></div><div className="provider-summary-row"><Card className="provider-summary-card"><div className="provider-summary-icon"><Zap size={19} /></div><div><StatusPill state="local">ALWAYS ON</StatusPill><h3>Free evidence engine</h3><p>{engine ? `v${engine.version} · ${engine.health.detail}` : 'Bounded extraction, evidence, drafts, and exports run without any provider account.'}</p></div></Card><Card className="provider-summary-card"><div className="provider-summary-icon"><Gauge size={19} /></div><div><StatusPill state={aiRoutes.some((route) => route.configured) ? 'live' : 'neutral'}>{aiRoutes.some((route) => route.configured) ? `${aiRoutes.filter((route) => route.configured).length} ROUTE(S) ACTIVE` : 'NO AI ROUTE YET'}</StatusPill><h3>Multi-route AI</h3><p>{aiRoutes.some((route) => route.configured) ? 'Failover across configured endpoints. Only supplied candidates are ever reordered.' : 'Configure AI_ROUTES server-side to activate free-tier ranking with automatic failover.'}</p></div></Card><Card className="provider-summary-card"><div className="provider-summary-icon"><Server size={19} /></div><div><StatusPill state={infra?.persistence === 'durable' ? 'live' : 'secure'}>{infra?.persistence === 'durable' ? 'DURABLE' : 'REQUEST-SCOPED'}</StatusPill><h3>Cache + storage</h3><p>{`Cache ${cacheMode}; fingerprint dedup v1.`}</p>{infra && <div className="infra-strip"><span>D1 {infra.bindings.d1 === 'configured' ? '✓' : '—'}</span><span>KV {infra.bindings.kv === 'configured' ? '✓' : '—'}</span><span>R2 {infra.bindings.r2 === 'configured' ? '✓' : '—'}</span><span>Queue {infra.bindings.queue === 'configured' ? '✓' : '—'}</span><span>Browser {infra.browserRun.status === 'ready' ? '✓' : '—'}</span><span>Workers AI {infra.workersAi.configured ? '✓' : '—'}</span></div>}</div></Card></div><Card className="provider-center-main"><SectionHeading eyebrow="LIVE INVENTORY" title="Routes, adapters, and limits" action={<button className="secondary-button" onClick={check}>{checking ? <LoaderCircle className="spin" size={15} /> : <RefreshCw size={15} />}{checking ? 'Refreshing' : 'Refresh'}</button>} /><div className="route-inventory">{aiRoutes.length ? aiRoutes.map((route) => <div className="route-row" key={route.id}><span className={clsx('capability-state', `capability-${route.configured ? 'ready' : 'not_configured'}`)}>{route.configured ? <Check size={14} /> : <Info size={14} />}</span><div><strong>{route.label}</strong><p>{route.reason}</p><small>{route.host ? `${route.host} · ${route.model}` : 'No endpoint configured'}{route.freeTier ? ' · free tier' : ''} · {route.costClass}</small></div><StatusPill state={route.configured ? 'live' : 'neutral'}>{route.configured ? 'Configured' : 'Not configured'}</StatusPill></div>) : <div className="route-empty"><Info size={18} /><p>No AI routes are configured. Add an OpenAI-compatible endpoint with a free tier as a server-side secret — the router will use it with automatic failover.</p></div>}</div><div className="provider-limit-strip">{data?.adapters?.map((adapter) => <span key={adapter.providerId}><strong>{adapter.label}</strong>{adapter.health.status} · v{adapter.version} · {adapter.limits.timeoutMs}ms · {adapter.limits.maxRetryAttempts} retries · fallback: {adapter.fallbackPriority.join(', ') || 'none'}</span>)}</div></Card><Card className="provider-guide-card"><SectionHeading eyebrow="FREE-TIER CONNECT GUIDE" title="OpenAI-compatible endpoints that work with the router" /><p className="guide-intro">Set these as server-side secrets (never in Git or client code). The router tries them in order and fails over on rate limits, auth failures, and timeouts. Example: <code>AI_ROUTES</code> = JSON array with <code>baseUrl</code>, <code>apiKey</code>, <code>model</code>, <code>freeTier</code>.</p><div className="guide-table"><div className="guide-row guide-head"><span>Provider</span><span>Endpoint host</span><span>Model</span><span>Tier</span><span>Notes</span></div>{FREE_ROUTE_GUIDE.map((entry) => <div className="guide-row" key={entry.provider}><span><strong>{entry.provider}</strong></span><span><code>{entry.host}</code></span><span>{entry.model}</span><span><StatusPill state="local">{entry.tier}</StatusPill></span><span>{entry.notes}</span></div>)}</div><div className="guide-foot"><ShieldCheck size={15} /><span>Every route is user-owned and documented. AiBay never bypasses rate limits, auth, or access controls — it respects provider responses and reports the real outcome.</span></div></Card></div>
}

const MISSION_LIST = [
  { id: 'listing_audit', label: 'Listing audit' }, { id: 'supplier_match', label: 'Supplier match' }, { id: 'product_arbitrage', label: 'Product arbitrage' },
  { id: 'competitor_deep_dive', label: 'Competitor deep dive' }, { id: 'trend_hunter', label: 'Trend hunter' }, { id: 'winning_products', label: 'Winning products' },
  { id: 'price_gap', label: 'Price gap hunter' }, { id: 'high_margin_products', label: 'High-margin products' }, { id: 'new_seller_analysis', label: 'New seller analysis' },
  { id: 'store_audit', label: 'Store audit' }, { id: 'category_opportunity', label: 'Category opportunity' }, { id: 'marketplace_comparison', label: 'Marketplace comparison' },
  { id: 'low_competition_products', label: 'Low-competition products' }, { id: 'dropshipping_candidates', label: 'Dropshipping candidates' },
]
type MissionPlan = { mission: string; label: string; description: string; steps: Array<{ step: number; task: string; capability: string; rationale: string; feasibility: string; reason: string }>; constraints: string[] }
function MissionControl({ notify }: { notify: (message: string) => void }) {
  const [mission, setMission] = useState('listing_audit')
  const [url, setUrl] = useState('')
  const [keyword, setKeyword] = useState('')
  const [consent, setConsent] = useState(false)
  const [plan, setPlan] = useState<MissionPlan | null>(null)
  const [running, setRunning] = useState(false)
  const [runResult, setRunResult] = useState<{ label: string; steps: Array<{ step: number; url: string; execution: { status: string; routeProvider?: string | null } }>; analysis: { priceStats: { count: number; min: number | null; max: number | null; median: number | null; average: number | null; state: string }; conflicts: unknown[]; graph: { nodeCount: number; edgeCount: number }; opportunity: { overall: number | null; verdict: string; explanation: string[] } }; report: string } | null>(null)
  const [oppInput, setOppInput] = useState({ title: '', observed: '', supplier: '', listings: '', keywordCount: '' })
  const [oppResult, setOppResult] = useState<{ overall: number | null; verdict: string; components: Array<{ key: string; label: string; value: number | null; state: string; evidence: string[] }>; explanation: string[] } | null>(null)
  const [priceLines, setPriceLines] = useState('2026-08-01,10\n2026-08-08,12\n2026-08-15,14')
  const [priceResult, setPriceResult] = useState<{ stats: { count: number; min: number | null; max: number | null; median: number | null; average: number | null; p10: number | null; p90: number | null; outliers: number[]; state: string }; trend: { trend: string; note: string } } | null>(null)
  const [evidenceLines, setEvidenceLines] = useState('Title|AeroStep Trail Runner|https://ebay.example/itm/1\nSource price|42 USD|https://ebay.example/itm/1\nSupplier price|18 USD|https://supplier.example/p')
  const [evidenceResult, setEvidenceResult] = useState<{ graph: { nodeCount: number; edgeCount: number; note: string }; conflicts: Array<{ field: string; values: unknown[]; note: string }>; sources: Array<{ host: string; score: number; state: string }> } | null>(null)

  const planMission = () => {
    void fetch('/api/research/missions', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ mission, inputs: { url, keyword } }) })
      .then(async (response) => await response.json() as { plan: MissionPlan } | { error: string })
      .then((payload) => { if ('plan' in payload) { setPlan(payload.plan); setRunResult(null); notify('Research plan ready.') } else notify('Unknown mission.') })
      .catch(() => notify('Mission planning is unavailable right now.'))
  }
  const runMission = () => {
    if (running) return
    setRunning(true)
    void fetch('/api/research/missions/run', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ mission, inputs: { url, keyword }, consent }) })
      .then(async (response) => await response.json() as typeof runResult)
      .then((payload) => { if (payload && 'analysis' in payload) { setRunResult(payload); setPlan(payload ? { mission, label: payload.label, description: '', steps: payload.steps.map((step, index) => ({ step: index + 1, task: 'product_import', capability: 'web.extract.public_metadata', rationale: '', feasibility: step.execution.status === 'completed' ? 'AVAILABLE' : 'BLOCKED', reason: step.execution.status })), constraints: [] } : null); notify('Mission run complete (bounded, request-scored).') } else notify('Mission could not run.') })
      .catch(() => notify('Mission execution is unavailable right now.'))
      .finally(() => setRunning(false))
  }
  const scoreOpportunity = () => {
    void fetch('/api/intelligence/opportunity', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ productTitle: oppInput.title, observedPrice: oppInput.observed ? Number(oppInput.observed) : null, supplierPrice: oppInput.supplier ? Number(oppInput.supplier) : null, keywordCount: oppInput.keywordCount ? Number(oppInput.keywordCount) : null, listings: oppInput.listings.split('\n').filter(Boolean).map((line) => ({ price: Number(line.trim()) })).filter((item) => Number.isFinite(item.price)) }) })
      .then(async (response) => await response.json() as typeof oppResult)
      .then(setOppResult).catch(() => notify('Opportunity scoring is unavailable right now.'))
  }
  const analyzePrices = () => {
    const prices = priceLines.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => { const [at, price] = line.split(','); return { at, price: Number(price) } }).filter((point) => point.at && Number.isFinite(point.price))
    void fetch('/api/intelligence/price', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ prices }) })
      .then(async (response) => await response.json() as typeof priceResult)
      .then(setPriceResult).catch(() => notify('Price analysis is unavailable right now.'))
  }
  const analyzeEvidence = () => {
    const observations = evidenceLines.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => { const [field, value, sourceUrl] = line.split('|'); return { field: field.trim(), value: value?.trim(), sourceUrl: sourceUrl?.trim(), sourceHost: sourceUrl ? new URL(sourceUrl).hostname : undefined } }).filter((item) => item.field && item.value)
    void fetch('/api/intelligence/evidence', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ observations }) })
      .then(async (response) => await response.json() as typeof evidenceResult)
      .then(setEvidenceResult).catch(() => notify('Evidence analysis is unavailable right now.'))
  }
  return <div className="mission-control-page"><div className="page-intro"><p className="eyebrow">MISSION CONTROL</p><h1>One-click research missions with explainable results.</h1><p>Pick a mission, add your source URL or keyword, and AiBay plans the research route, runs bounded steps through the router, and scores the evidence. Every number is computed from supplied observations — nothing is invented.</p></div>
    <Card className="mission-picker-card"><SectionHeading eyebrow="RESEARCH MISSIONS" title="What should AiBay research?" /><div className="mission-grid">{MISSION_LIST.map((entry) => <button key={entry.id} className={clsx('mission-chip', mission === entry.id && 'selected')} onClick={() => setMission(entry.id)}>{entry.label}</button>)}</div><div className="mission-inputs"><input aria-label="Mission source URL" value={url} onChange={(event) => setUrl(event.target.value)} placeholder="Source URL (for extract/audit missions)" /><input aria-label="Mission keyword" value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="Keyword (for search missions)" /><button className="secondary-button" onClick={planMission}><Search size={15} /> Plan mission</button><button className="primary-button" disabled={!url.trim() || !consent || running} onClick={runMission}>{running ? <LoaderCircle className="spin" size={16} /> : <Zap size={16} />}{running ? 'Running bounded mission' : 'Run mission'}</button></div><label className="consent-control mission-consent"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} /><span>I have the right to use the source information and any assets involved.</span></label>{plan && <div className="mission-plan"><p className="eyebrow">PLAN · {plan.label}</p><p className="plan-desc">{plan.description}</p><div className="plan-steps">{plan.steps.map((step) => <div className="plan-step" key={step.step}><span>{step.step}</span><div><strong>{step.capability}</strong><p>{step.rationale || step.reason}</p></div><StatusPill state={step.feasibility === 'AVAILABLE' ? 'local' : step.feasibility === 'UNCONFIGURED' ? 'warn' : 'neutral'}>{step.feasibility}</StatusPill></div>)}</div><p className="plan-constraints">{plan.constraints.join(' · ')}</p></div>}{runResult && <div className="mission-run-result"><p className="eyebrow">RUN RESULT · {runResult.label}</p><div className="plan-steps">{runResult.steps.map((step) => <div className="plan-step" key={step.step}><span>{step.step}</span><div><strong>{step.url}</strong><p>Route: {step.execution.routeProvider ?? 'n/a'}</p></div><StatusPill state={step.execution.status === 'completed' ? 'local' : 'warn'}>{step.execution.status}</StatusPill></div>)}</div><div className="mission-analysis-grid"><div className="analysis-mini"><span className="eyebrow">PRICE OBSERVATIONS</span><strong>{runResult.analysis.priceStats.count} pts · avg {runResult.analysis.priceStats.average ?? '—'}</strong><small>{runResult.analysis.priceStats.state}</small></div><div className="analysis-mini"><span className="eyebrow">OPPORTUNITY</span><strong>{runResult.analysis.opportunity.overall != null ? `${runResult.analysis.opportunity.overall}/100 · ${runResult.analysis.opportunity.verdict}` : 'INSUFFICIENT EVIDENCE'}</strong><small>{runResult.analysis.opportunity.explanation[0]?.slice(0, 110)}</small></div><div className="analysis-mini"><span className="eyebrow">EVIDENCE GRAPH</span><strong>{runResult.analysis.graph.nodeCount} entities · {runResult.analysis.graph.edgeCount} links</strong><small>{runResult.analysis.conflicts.length} conflict(s) surfaced, none resolved silently</small></div></div><details className="report-details"><summary>View research report (Markdown)</summary><pre className="report-pre">{runResult.report}</pre></details></div>}</Card>
    <div className="mission-columns"><Card className="mission-tool-card"><SectionHeading eyebrow="OPPORTUNITY SCORER" title="Explainable product opportunity" /><div className="tool-form"><input aria-label="Product title" placeholder="Product title" value={oppInput.title} onChange={(event) => setOppInput({ ...oppInput, title: event.target.value })} /><div className="tool-form-row"><input aria-label="Observed market price" placeholder="Observed price" inputMode="decimal" value={oppInput.observed} onChange={(event) => setOppInput({ ...oppInput, observed: event.target.value })} /><input aria-label="Supplier price" placeholder="Supplier price" inputMode="decimal" value={oppInput.supplier} onChange={(event) => setOppInput({ ...oppInput, supplier: event.target.value })} /><input aria-label="Keyword count" placeholder="Keyword count" inputMode="numeric" value={oppInput.keywordCount} onChange={(event) => setOppInput({ ...oppInput, keywordCount: event.target.value })} /></div><textarea aria-label="Listing prices (one per line)" placeholder={'Competing listing prices, one per line\n42\n45\n39'} rows={3} value={oppInput.listings} onChange={(event) => setOppInput({ ...oppInput, listings: event.target.value })} /><button className="secondary-button full" onClick={scoreOpportunity}><BarChart3 size={15} /> Score opportunity</button></div>{oppResult && <div className="opp-result"><div className="opp-overall"><span className="eyebrow">OVERALL</span><strong>{oppResult.overall != null ? `${oppResult.overall}/100` : '—'}</strong><StatusPill state={oppResult.verdict === 'OPPORTUNITY' ? 'live' : oppResult.verdict === 'INSUFFICIENT_EVIDENCE' ? 'warn' : 'neutral'}>{oppResult.verdict}</StatusPill></div><div className="opp-components">{oppResult.components.map((component) => <div className="opp-component" key={component.key}><div><strong>{component.label}</strong><small>{component.state}</small></div><div className="opp-bar"><i style={{ width: `${component.value ?? 0}%`, opacity: component.value == null ? 0.15 : 1 }} /></div><span>{component.value ?? '—'}</span></div>)}</div><ul className="opp-explanation">{oppResult.explanation.map((line, index) => <li key={`${line}-${index}`}>{line}</li>)}</ul></div>}</Card>
    <Card className="mission-tool-card"><SectionHeading eyebrow="PRICE INTELLIGENCE" title="Statistics, outliers, and trend class" /><div className="tool-form"><textarea aria-label="Dated prices" placeholder={'date,price\n2026-08-01,10\n2026-08-08,12'} rows={3} value={priceLines} onChange={(event) => setPriceLines(event.target.value)} /><button className="secondary-button full" onClick={analyzePrices}><LineChart size={15} /> Analyze prices</button></div>{priceResult && <div className="price-result"><div className="price-stat-grid"><span><small>Count</small><strong>{priceResult.stats.count}</strong></span><span><small>Min</small><strong>{priceResult.stats.min ?? '—'}</strong></span><span><small>Max</small><strong>{priceResult.stats.max ?? '—'}</strong></span><span><small>Median</small><strong>{priceResult.stats.median ?? '—'}</strong></span><span><small>Avg</small><strong>{priceResult.stats.average ?? '—'}</strong></span><span><small>p10–p90</small><strong>{priceResult.stats.p10 ?? '—'}–{priceResult.stats.p90 ?? '—'}</strong></span></div><div className="trend-pill"><StatusPill state={priceResult.trend.trend === 'RISING' ? 'live' : priceResult.trend.trend === 'FALLING' ? 'warn' : priceResult.trend.trend === 'INSUFFICIENT_DATA' ? 'neutral' : 'local'}>{priceResult.trend.trend}</StatusPill><span>{priceResult.trend.note}</span></div>{priceResult.stats.outliers.length > 0 && <p className="outlier-note">Outliers: {priceResult.stats.outliers.join(', ')}</p>}</div>}</Card></div>
    <Card className="mission-tool-card"><SectionHeading eyebrow="EVIDENCE GRAPH" title="Entities, relationships, conflicts, and source quality" /><div className="tool-form"><textarea aria-label="Observations (field|value|url)" placeholder={'field|value|sourceUrl\nTitle|AeroStep Trail Runner|https://ebay.example/itm/1\nSource price|42 USD|https://ebay.example/itm/1'} rows={4} value={evidenceLines} onChange={(event) => setEvidenceLines(event.target.value)} /><button className="secondary-button full" onClick={analyzeEvidence}><Network size={15} /> Build evidence graph</button></div>{evidenceResult && <div className="evidence-result"><div className="evidence-summary"><StatusPill state="local">{evidenceResult.graph.nodeCount} entities · {evidenceResult.graph.edgeCount} relationships</StatusPill><p>{evidenceResult.graph.note}</p></div>{evidenceResult.conflicts.length > 0 ? <div className="conflict-list">{evidenceResult.conflicts.map((conflict) => <div className="conflict-entry" key={conflict.field}><AlertTriangle size={14} /><div><strong>CONFLICT · {conflict.field}</strong><p>{conflict.note}</p></div></div>)}</div> : <p className="no-conflicts"><Check size={14} /> No contradictory values across supplied observations.</p>}{evidenceResult.sources.length > 0 && <div className="source-score-list">{evidenceResult.sources.map((source) => <div className="source-score" key={source.host}><span>{source.host}</span><StatusPill state={source.state === 'VERIFIED' ? 'local' : source.state === 'PARTIAL' ? 'neutral' : 'warn'}>{source.state}</StatusPill><strong>{source.score}/100</strong></div>)}</div>}</div>}</Card>
  </div>
}

type VaultItem = { id: string; kind: 'watch' | 'seller'; title: string; url: string; targetPrice?: string | null; note?: string | null; createdAt: string }
type Vault = { watchlist: Array<{ id: string; title: string; url: string; targetPrice: string; addedAt: string; note: string }>; trackedSellers: Array<{ id: string; name: string; url: string; addedAt: string }>; generated: Array<{ id: string; title: string; createdAt: string }>; scans: Array<{ id: string; urlCount: number; priceCount: number; createdAt: string }> }
const EMPTY_VAULT: Vault = { watchlist: [], trackedSellers: [], generated: [], scans: [] }
function loadVault(): Vault {
  try { const raw = localStorage.getItem('aibay.vault.v1'); return raw ? { ...EMPTY_VAULT, ...JSON.parse(raw) } : EMPTY_VAULT } catch { return EMPTY_VAULT }
}
function saveVault(vault: Vault) { try { localStorage.setItem('aibay.vault.v1', JSON.stringify(vault)) } catch { /* storage unavailable */ } }
const TOOL_TABS = ['Generator', 'Scanner', 'Keywords', 'Profit', 'Trending', 'Watchlist'] as const
type ToolTab = typeof TOOL_TABS[number]
function ToolSuite({ notify }: { notify: (message: string) => void }) {
  const [tab, setTab] = useState<ToolTab>('Generator')
  const [vault, setVault] = useState<Vault>(loadVault)
  const [serverPersistence, setServerPersistence] = useState<'durable' | 'request_only' | 'unknown'>('unknown')
  const updateVault = (next: Vault) => { setVault(next); saveVault(next) }
  useEffect(() => {
    let cancelled = false
    void fetch('/api/vault', { headers: { accept: 'application/json' } })
      .then(async (response) => ({ response, payload: await response.json() as { persistence?: string; items?: VaultItem[]; stats?: { watch: number; sellers: number; generated: number; scans: number } } }))
      .then(({ response, payload }) => {
        if (cancelled) return
        if (response.ok && payload.persistence === 'durable' && payload.items) {
          const items = payload.items
          const watchlist = items.filter((item) => item.kind === 'watch').map((item) => ({ id: item.id, title: item.title, url: item.url, targetPrice: item.targetPrice ?? '', addedAt: item.createdAt, note: item.note ?? '' }))
          const trackedSellers = items.filter((item) => item.kind === 'seller').map((item) => ({ id: item.id, name: item.title, url: item.url, addedAt: item.createdAt }))
          setVault({ watchlist, trackedSellers, generated: vault.generated, scans: vault.scans })
          setServerPersistence('durable')
        } else {
          setServerPersistence('request_only')
        }
      })
      .catch(() => { if (!cancelled) setServerPersistence('request_only') })
    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  const syncServer = (action: 'add' | 'remove', item: { kind: 'watch' | 'seller'; title: string; url: string; targetPrice?: string; note?: string; id?: string }) => {
    if (serverPersistence !== 'durable') return
    void fetch('/api/vault', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action, ...item }) })
      .then(async (response) => await response.json() as { status?: string; items?: VaultItem[]; stats?: { watch: number; sellers: number; generated: number; scans: number } })
      .then((payload) => {
        if (payload?.status === 'ok' && payload.items) {
          const watchlist = payload.items.filter((entry) => entry.kind === 'watch').map((entry) => ({ id: entry.id, title: entry.title, url: entry.url, targetPrice: entry.targetPrice ?? '', addedAt: entry.createdAt, note: entry.note ?? '' }))
          const trackedSellers = payload.items.filter((entry) => entry.kind === 'seller').map((entry) => ({ id: entry.id, name: entry.title, url: entry.url, addedAt: entry.createdAt }))
          setVault((previous) => ({ ...previous, watchlist, trackedSellers }))
        }
      })
      .catch(() => undefined)
  }
  // Generator
  const [gen, setGen] = useState({ title: '', brand: '', model: '', description: '', supplierCost: '', marketPrice: '', currency: 'USD' })
  const [genResult, setGenResult] = useState<{ listingPackage: { titleCandidates: string[]; description: string; itemSpecifics: Array<{ label: string; value: string; state: string }> }; titleScore: { score: number; suggestions: string[]; improvedTitle: string | null }; categorySuggestions: Array<{ name: string; confidence: number; matchedKeywords: string[] }>; profit?: { estimatedProfit: number; marginPct: number | null; breakevenPrice: number; currency: string; lineItems: Array<{ label: string; amount: number }>; assumptions: string[] } } | null>(null)
  const runGenerate = () => {
    void fetch('/api/tools/generate', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ productTitle: gen.title, brand: gen.brand, model: gen.model, description: gen.description, currency: gen.currency, supplierCost: gen.supplierCost ? Number(gen.supplierCost) : null, market: gen.marketPrice ? [{ title: gen.title, price: Number(gen.marketPrice) }] : [] }) })
      .then(async (response) => await response.json() as typeof genResult)
      .then((payload) => { if (payload && 'listingPackage' in payload) { setGenResult(payload); updateVault({ ...vault, generated: [{ id: `gen_${Date.now()}`, title: payload.listingPackage.titleCandidates[0] ?? gen.title, createdAt: new Date().toISOString() }, ...vault.generated].slice(0, 50) }); notify('Listing package generated (draft-only).') } else notify('Generation needs a title.') })
      .catch(() => notify('Listing generation is unavailable right now.'))
  }
  // Scanner
  const [scanUrls, setScanUrls] = useState('')
  const [scanConsent, setScanConsent] = useState(false)
  const [scanResult, setScanResult] = useState<{ requested: number; accepted: number; droppedDuplicates: number; results: Array<{ url: string; host: string; status: string; title: string | null; price: number | null; error: string | null }>; priceStats: { count: number; min: number | null; max: number | null; median: number | null; state: string }; dedup: { duplicateCount: number } } | null>(null)
  const runScanner = () => {
    const urls = scanUrls.split('\n').map((line) => line.trim()).filter(Boolean)
    if (!urls.length) { notify('Paste at least one public URL.'); return }
    void fetch('/api/tools/scanner', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ urls, consent: scanConsent }) })
      .then(async (response) => await response.json() as typeof scanResult)
      .then((payload) => { if (payload && 'results' in payload) { setScanResult(payload); updateVault({ ...vault, scans: [{ id: `scan_${Date.now()}`, urlCount: payload.accepted, priceCount: payload.priceStats.count, createdAt: new Date().toISOString() }, ...vault.scans].slice(0, 50) }); notify(`Scanner finished: ${payload.accepted} URL(s) accepted, ${payload.priceStats.count} price observation(s).`) } })
      .catch(() => notify('Scanner is unavailable right now.'))
  }
  // Keywords
  const [kw, setKw] = useState({ title: '', description: '', sold: '', active: '' })
  const [kwResult, setKwResult] = useState<{ groups: Array<{ label: string; tokens: string[] }>; suggestedTitles: Array<{ title: string; length: number }>; coverage: { coveragePct: number | null }; sellThrough: { state: string; ratePct: number | null } | null; note: string } | null>(null)
  const runKeywords = () => {
    void fetch('/api/tools/keywords', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: kw.title, description: kw.description, soldVolume: kw.sold ? Number(kw.sold) : null, activeVolume: kw.active ? Number(kw.active) : null }) })
      .then(async (response) => await response.json() as typeof kwResult)
      .then((payload) => { if (payload && 'groups' in payload) { setKwResult(payload); notify('Keyword analysis complete.') } else notify('A product title is required.') })
      .catch(() => notify('Keyword studio is unavailable right now.'))
  }
  // Profit
  const [pf, setPf] = useState({ revenue: '', supplierCost: '', shipping: '', adPct: '', platformPct: '13.25', paymentPct: '2.9', currency: 'USD' })
  const [pfResult, setPfResult] = useState<{ estimatedProfit: number; marginPct: number | null; breakevenPrice: number; currency: string; lineItems: Array<{ label: string; amount: number }>; assumptions: string[]; note: string } | null>(null)
  const runProfit = () => {
    void fetch('/api/tools/profit', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ revenue: pf.revenue ? Number(pf.revenue) : null, supplierCost: pf.supplierCost ? Number(pf.supplierCost) : null, shippingCost: pf.shipping ? Number(pf.shipping) : null, adFeePct: pf.adPct ? Number(pf.adPct) : null, platformFeePct: pf.platformPct ? Number(pf.platformPct) : null, paymentFeePct: pf.paymentPct ? Number(pf.paymentPct) : null, currency: pf.currency }) })
      .then(async (response) => await response.json() as typeof pfResult)
      .then((payload) => { if (payload && 'estimatedProfit' in payload) { setPfResult(payload); notify('Profit estimate computed (ESTIMATED — not a guarantee).') } else notify('Revenue and supplier cost are required.') })
      .catch(() => notify('Profit calculator is unavailable right now.'))
  }
  // Trending
  const [trLines, setTrLines] = useState('wireless earbuds|2026-08-01,10\nwireless earbuds|2026-08-08,15\nwireless earbuds|2026-08-15,21')
  const [trResult, setTrResult] = useState<{ hotCount: number; items: Array<{ keyword: string; deltaPct: number | null; observations: number; state: string; note: string }>; note: string } | null>(null)
  const runTrending = () => {
    const series: Array<{ keyword: string; observations: Array<{ date: string; count: number }> }> = []
    const byKeyword = new Map<string, Array<{ date: string; count: number }>>()
    for (const line of trLines.split('\n').map((line) => line.trim()).filter(Boolean)) {
      const [keyword, rest] = line.split('|')
      const [date, count] = (rest ?? '').split(',')
      if (!keyword || !date || !Number.isFinite(Number(count))) continue
      const list = byKeyword.get(keyword) ?? []
      list.push({ date, count: Number(count) })
      byKeyword.set(keyword, list)
    }
    for (const [keyword, observations] of byKeyword) series.push({ keyword, observations })
    void fetch('/api/trends/hot', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ series }) })
      .then(async (response) => await response.json() as typeof trResult)
      .then(setTrResult).catch(() => notify('Trending analysis is unavailable right now.'))
  }
  // Watchlist
  const [wl, setWl] = useState({ title: '', url: '', target: '', note: '' })
  const [seller, setSeller] = useState({ name: '', url: '' })
  const addWatch = () => { if (!wl.title.trim() || !wl.url.trim()) { notify('Watch item needs a title and URL.'); return } const item = { id: `wl_${Date.now()}`, title: wl.title, url: wl.url, targetPrice: wl.target, addedAt: new Date().toISOString(), note: wl.note }; updateVault({ ...vault, watchlist: [item, ...vault.watchlist].slice(0, 100) }); syncServer('add', { kind: 'watch', title: wl.title, url: wl.url, targetPrice: wl.target, note: wl.note }); setWl({ title: '', url: '', target: '', note: '' }); notify(serverPersistence === 'durable' ? 'Watch item saved to the durable vault.' : 'Watch item saved to this browser (local vault).') }
  const addSeller = () => { if (!seller.name.trim() || !seller.url.trim()) { notify('Tracked seller needs a name and store URL.'); return } updateVault({ ...vault, trackedSellers: [{ id: `ts_${Date.now()}`, name: seller.name, url: seller.url, addedAt: new Date().toISOString() }, ...vault.trackedSellers].slice(0, 100) }); syncServer('add', { kind: 'seller', title: seller.name, url: seller.url }); setSeller({ name: '', url: '' }); notify(serverPersistence === 'durable' ? 'Seller saved to the durable vault.' : 'Seller saved to this browser (local vault).') }
  const exportVault = () => { const blob = new Blob([JSON.stringify(vault, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'aibay-vault.json'; anchor.click(); URL.revokeObjectURL(url) }
  const importVault = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)); if (parsed && typeof parsed === 'object') { updateVault({ ...EMPTY_VAULT, ...parsed }); notify('Vault imported.') } } catch { notify('Vault file is not valid JSON.') } }; reader.readAsText(file); event.target.value = '' }
  return <div className="tool-suite-page"><div className="page-intro"><p className="eyebrow">TOOL SUITE</p><h1>Generate, scan, keyword, price, trend, and watch — with evidence.</h1><p>Every tool computes from what you supply. Nothing is fabricated; watchlist and trackers live in this browser (local vault) until durable storage is configured.</p></div><div className="tool-tabs">{TOOL_TABS.map((entry) => <button key={entry} className={clsx('tool-tab', tab === entry && 'selected')} onClick={() => setTab(entry)}>{entry}</button>)}</div>
    {tab === 'Generator' && <Card className="tool-panel"><SectionHeading eyebrow="AIBAY GENERATOR" title="Evidence-grounded eBay listing draft" action={<StatusPill state="secure">Draft-only</StatusPill>} /><div className="tool-form"><div className="tool-form-row three"><input aria-label="Product title" placeholder="Product title (from your evidence)" value={gen.title} onChange={(event) => setGen({ ...gen, title: event.target.value })} /><input aria-label="Brand" placeholder="Brand" value={gen.brand} onChange={(event) => setGen({ ...gen, brand: event.target.value })} /><input aria-label="Model" placeholder="Model" value={gen.model} onChange={(event) => setGen({ ...gen, model: event.target.value })} /></div><textarea aria-label="Description" placeholder="Description or notes (facts you are entitled to use)" rows={3} value={gen.description} onChange={(event) => setGen({ ...gen, description: event.target.value })} /><div className="tool-form-row three"><input aria-label="Supplier cost" placeholder="Supplier cost" inputMode="decimal" value={gen.supplierCost} onChange={(event) => setGen({ ...gen, supplierCost: event.target.value })} /><input aria-label="Observed market price" placeholder="Observed market price" inputMode="decimal" value={gen.marketPrice} onChange={(event) => setGen({ ...gen, marketPrice: event.target.value })} /><select aria-label="Currency" value={gen.currency} onChange={(event) => setGen({ ...gen, currency: event.target.value })}><option>USD</option><option>EUR</option><option>GBP</option><option>CAD</option></select></div><button className="primary-button full" onClick={runGenerate}><Sparkles size={16} /> Generate listing package</button></div>{genResult && <div className="gen-result"><div className="gen-title-score"><div><span className="eyebrow">TITLE SCORE</span><strong>{genResult.titleScore.score}/100</strong></div><StatusPill state={genResult.titleScore.score >= 70 ? 'local' : 'warn'}>{genResult.titleScore.score >= 70 ? 'Good' : 'Needs work'}</StatusPill></div>{genResult.titleScore.improvedTitle && <p className="improved-title">Improved: {genResult.titleScore.improvedTitle}</p>}{genResult.titleScore.suggestions.length > 0 && <ul className="suggestion-list">{genResult.titleScore.suggestions.map((suggestion) => <li key={suggestion}>{suggestion}</li>)}</ul>}<div className="gen-candidates">{genResult.listingPackage.titleCandidates.map((candidate) => <div className="gen-candidate" key={candidate}><Check size={14} /><span>{candidate}</span><small>{candidate.length}/80</small></div>)}</div>{genResult.categorySuggestions.length > 0 && <div className="gen-categories">{genResult.categorySuggestions.map((category) => <span key={category.name}><strong>{category.name}</strong> {category.confidence}% · {category.matchedKeywords.join(', ')}</span>)}</div>}{genResult.profit && <div className="gen-profit"><span className="eyebrow">PROFIT ESTIMATE (ESTIMATED)</span><strong>{genResult.profit.currency} {genResult.profit.estimatedProfit}</strong><small>{genResult.profit.marginPct ?? '—'}% margin · breakeven {genResult.profit.currency} {genResult.profit.breakevenPrice}</small></div>}</div>}</Card>}
    {tab === 'Scanner' && <Card className="tool-panel"><SectionHeading eyebrow="TURBO SCANNER" title="Bounded batch research across sources" action={<StatusPill state="secure">Bounded</StatusPill>} /><p className="tool-hint">Max 10 URLs · 3 per domain · 2 concurrent · 1 attempt each. Blocked and capped entries are reported, never hidden.</p><textarea aria-label="URLs (one per line)" placeholder={'Paste public product URLs, one per line\nhttps://store.example.com/products/a'} rows={6} value={scanUrls} onChange={(event) => setScanUrls(event.target.value)} /><label className="consent-control"><input type="checkbox" checked={scanConsent} onChange={(event) => setScanConsent(event.target.checked)} /><span>I have the right to use these sources and their information.</span></label><button className="primary-button full" disabled={!scanConsent} onClick={runScanner}><PackageSearch size={16} /> Run bounded scan</button>{scanResult && <div className="scan-result"><div className="scan-summary"><span><strong>{scanResult.accepted}</strong><small>URLs accepted</small></span><span><strong>{scanResult.priceStats.count}</strong><small>price observations</small></span><span><strong>{scanResult.droppedDuplicates}</strong><small>duplicates dropped</small></span><span><strong>{scanResult.dedup.duplicateCount}</strong><small>collapsed in results</small></span></div><div className="scan-table">{scanResult.results.map((row) => <div className="scan-row" key={row.url}><StatusPill state={row.status === 'completed' ? 'local' : row.status === 'blocked' ? 'warn' : 'neutral'}>{row.status}</StatusPill><div><strong>{row.title ?? row.url}</strong><small>{row.host} · {row.price != null ? `${row.price}` : 'no price observed'}{row.error ? ` · ${row.error}` : ''}</small></div></div>)}</div>{scanResult.priceStats.count > 0 && <p className="scan-price-note">Min {scanResult.priceStats.min} · median {scanResult.priceStats.median} · max {scanResult.priceStats.max} ({scanResult.priceStats.state})</p>}</div>}</Card>}
    {tab === 'Keywords' && <Card className="tool-panel"><SectionHeading eyebrow="KEYWORD STUDIO" title="Deterministic keyword groups and title suggestions" /><div className="tool-form"><input aria-label="Product title" placeholder="Product title" value={kw.title} onChange={(event) => setKw({ ...kw, title: event.target.value })} /><textarea aria-label="Description" placeholder="Description (for coverage check)" rows={2} value={kw.description} onChange={(event) => setKw({ ...kw, description: event.target.value })} /><div className="tool-form-row two"><input aria-label="Sold volume (optional)" placeholder="Sold volume (optional)" inputMode="numeric" value={kw.sold} onChange={(event) => setKw({ ...kw, sold: event.target.value })} /><input aria-label="Active volume (optional)" placeholder="Active volume (optional)" inputMode="numeric" value={kw.active} onChange={(event) => setKw({ ...kw, active: event.target.value })} /></div><button className="primary-button full" onClick={runKeywords}><Tag size={16} /> Analyze keywords</button></div>{kwResult && <div className="kw-result"><div className="kw-groups">{kwResult.groups.map((group) => <div className="kw-group" key={group.label}><strong>{group.label}</strong><span>{group.tokens.join(', ') || '—'}</span></div>)}</div>{kwResult.sellThrough ? <p className="str-line"><StatusPill state="live">STR {kwResult.sellThrough.ratePct}%</StatusPill> {kwResult.note}</p> : <p className="str-unverified"><Info size={14} /> {kwResult.note}</p>}<div className="kw-suggestions">{kwResult.suggestedTitles.map((suggestion) => <div className="kw-suggestion" key={suggestion.title}><span>{suggestion.title}</span><small>{suggestion.length}/80</small></div>)}</div>{kwResult.coverage.coveragePct != null && <p className="coverage-line">Description keyword coverage: {kwResult.coverage.coveragePct}%</p>}</div>}</Card>}
    {tab === 'Profit' && <Card className="tool-panel"><SectionHeading eyebrow="PROFIT CALCULATOR" title="Fee-aware estimate with exposed assumptions" action={<StatusPill state="warn">ESTIMATED</StatusPill>} /><div className="tool-form"><div className="tool-form-row three"><input aria-label="Revenue" placeholder="Revenue (observed price)" inputMode="decimal" value={pf.revenue} onChange={(event) => setPf({ ...pf, revenue: event.target.value })} /><input aria-label="Supplier cost" placeholder="Supplier cost" inputMode="decimal" value={pf.supplierCost} onChange={(event) => setPf({ ...pf, supplierCost: event.target.value })} /><input aria-label="Shipping cost" placeholder="Shipping cost" inputMode="decimal" value={pf.shipping} onChange={(event) => setPf({ ...pf, shipping: event.target.value })} /></div><div className="tool-form-row three"><label className="fee-field">Platform fee %<input aria-label="Platform fee percent" inputMode="decimal" value={pf.platformPct} onChange={(event) => setPf({ ...pf, platformPct: event.target.value })} /></label><label className="fee-field">Payment fee %<input aria-label="Payment fee percent" inputMode="decimal" value={pf.paymentPct} onChange={(event) => setPf({ ...pf, paymentPct: event.target.value })} /></label><label className="fee-field">Ad fee %<input aria-label="Ad fee percent" inputMode="decimal" value={pf.adPct} onChange={(event) => setPf({ ...pf, adPct: event.target.value })} /></label></div><button className="primary-button full" onClick={runProfit}><BarChart3 size={16} /> Calculate estimate</button></div>{pfResult && <div className="pf-result"><div className="pf-hero"><div><span className="eyebrow">ESTIMATED PROFIT</span><strong>{pfResult.currency} {pfResult.estimatedProfit}</strong><small>{pfResult.marginPct != null ? `${pfResult.marginPct}% margin` : '—'} · breakeven {pfResult.currency} {pfResult.breakevenPrice}</small></div><StatusPill state={pfResult.estimatedProfit >= 0 ? 'local' : 'warn'}>{pfResult.estimatedProfit >= 0 ? 'Positive' : 'Loss'}</StatusPill></div><div className="pf-lines">{pfResult.lineItems.map((item) => <div className="pf-line" key={item.label}><span>{item.label}</span><strong>{pfResult.currency} {item.amount}</strong></div>)}</div><p className="pf-note">{pfResult.note}</p><ul className="pf-assumptions">{pfResult.assumptions.map((assumption) => <li key={assumption}>{assumption}</li>)}</ul></div>}</Card>}
    {tab === 'Trending' && <Card className="tool-panel"><SectionHeading eyebrow="EVIDENCE-GATED TRENDING" title="HOT only with ≥3 dated observations and ≥20% delta" action={<StatusPill state="secure">No fabrication</StatusPill>} /><textarea aria-label="Trend series (keyword|date,count per line)" placeholder={'keyword|date,count\nwireless earbuds|2026-08-01,10\nwireless earbuds|2026-08-08,15'} rows={5} value={trLines} onChange={(event) => setTrLines(event.target.value)} /><button className="primary-button full" onClick={runTrending}><LineChart size={16} /> Analyze trend evidence</button>{trResult && <div className="tr-result"><div className="tr-items">{trResult.items.map((item) => <div className={clsx('tr-item', item.state === 'HOT' && 'hot')} key={item.keyword}><div><strong>{item.keyword}</strong><small>{item.note}</small></div><StatusPill state={item.state === 'HOT' ? 'live' : 'neutral'}>{item.state}</StatusPill></div>)}</div><p className="tr-note">{trResult.note}</p></div>}</Card>}
    {tab === 'Watchlist' && <Card className="tool-panel"><SectionHeading eyebrow="VAULT" title="Watchlist, tracked sellers, and saved work" action={<div className="vault-actions"><StatusPill state={serverPersistence === 'durable' ? 'live' : 'neutral'}>{serverPersistence === 'durable' ? 'Durable vault' : serverPersistence === 'unknown' ? 'Checking…' : 'Browser vault'}</StatusPill><button className="secondary-button" onClick={exportVault}><Download size={14} /> Export</button><label className="secondary-button"><Upload size={14} /> Import<input type="file" accept="application/json" style={{ display: 'none' }} onChange={importVault} /></label></div>} /><div className="vault-grid"><div className="vault-col"><p className="eyebrow">WATCHLIST · {vault.watchlist.length}</p><div className="vault-list">{vault.watchlist.map((item) => <div className="vault-row" key={item.id}><div><strong>{item.title}</strong><small>{item.url}{item.targetPrice ? ` · target ${item.targetPrice}` : ''}</small></div><button className="icon-button" aria-label="Remove watch item" onClick={() => { syncServer('remove', { kind: 'watch', title: '', url: '', id: item.id }); updateVault({ ...vault, watchlist: vault.watchlist.filter((entry) => entry.id !== item.id) }) }}><X size={14} /></button></div>)}</div><div className="tool-form vault-form"><input aria-label="Watch item title" placeholder="Product title" value={wl.title} onChange={(event) => setWl({ ...wl, title: event.target.value })} /><input aria-label="Watch item URL" placeholder="https://…" value={wl.url} onChange={(event) => setWl({ ...wl, url: event.target.value })} /><div className="tool-form-row two"><input aria-label="Target price" placeholder="Target price" inputMode="decimal" value={wl.target} onChange={(event) => setWl({ ...wl, target: event.target.value })} /><input aria-label="Watch note" placeholder="Note" value={wl.note} onChange={(event) => setWl({ ...wl, note: event.target.value })} /></div><button className="secondary-button" onClick={addWatch}>Add watch item</button></div></div><div className="vault-col"><p className="eyebrow">TRACKED SELLERS · {vault.trackedSellers.length}</p><div className="vault-list">{vault.trackedSellers.map((item) => <div className="vault-row" key={item.id}><div><strong>{item.name}</strong><small>{item.url}</small></div><button className="icon-button" aria-label="Remove seller" onClick={() => { syncServer('remove', { kind: 'seller', title: '', url: '', id: item.id }); updateVault({ ...vault, trackedSellers: vault.trackedSellers.filter((entry) => entry.id !== item.id) }) }}><X size={14} /></button></div>)}</div><div className="tool-form vault-form"><input aria-label="Seller name" placeholder="Seller name" value={seller.name} onChange={(event) => setSeller({ ...seller, name: event.target.value })} /><input aria-label="Seller store URL" placeholder="https://…" value={seller.url} onChange={(event) => setSeller({ ...seller, url: event.target.value })} /><button className="secondary-button" onClick={addSeller}>Track seller</button></div></div></div><div className="vault-stats"><span><strong>{vault.generated.length}</strong><small>listings generated</small></span><span><strong>{vault.scans.length}</strong><small>scans run</small></span><span><strong>{vault.watchlist.length + vault.trackedSellers.length}</strong><small>monitored items</small></span><p>Vault is browser-local (this device) and exported/imported as JSON. Durable cloud sync is a configured-infrastructure migration.</p></div></Card>}
  </div>
}

function ProductResearchLab({ notify }: { notify: (message: string) => void }) {
  const [rows, setRows] = useState([{ sourceUrl: '', title: '', brand: '', model: '', price: '' }])
  const [result, setResult] = useState<{ status: string; candidates?: Array<{ title: string; sourceUrl: string; canonicalUrl?: string; fingerprint?: string; brand?: string; model?: string; price?: number | null; currency?: string | null; score: { total: number; explanation: string[] }; validation: { missing: string[]; warnings?: string[] } }>; duplicateCount?: number; note?: string } | null>(null)
  const [running, setRunning] = useState(false)
  const update = (index: number, key: keyof typeof rows[number], value: string) => setRows((previous) => previous.map((row, rowIndex) => rowIndex === index ? { ...row, [key]: value } : row))
  const exportResults = async (format: 'json' | 'csv' | 'markdown') => {
    if (!result?.candidates?.length) return
    const response = await fetch('/api/exports/research', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ format, results: result.candidates }) })
    if (!response.ok) { notify('Research export could not be created.'); return }
    const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `aibay-research.${format === 'markdown' ? 'md' : format}`; anchor.click(); URL.revokeObjectURL(url); notify(`${format.toUpperCase()} research export downloaded.`)
  }
  const run = () => {
    const candidates = rows.filter((row) => row.sourceUrl.trim() && row.title.trim()).map((row) => ({ ...row, price: row.price ? Number(row.price) : null, currency: 'USD', sourceReliability: 60, evidence: [{ label: 'Title', value: row.title, source: row.sourceUrl }] }))
    if (!candidates.length) { notify('Add at least one source URL and product title.'); return }
    setRunning(true)
    void fetch('/api/products/research', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ candidates }) }).then(async (response) => await response.json() as typeof result).then((payload) => { setResult(payload); notify(payload?.status === 'completed' ? 'Research candidates normalized and ranked.' : 'No approved discovery provider is configured; supplied candidates were not expanded.') }).catch(() => notify('Research pipeline unavailable. Your candidate fields remain local to this session.')).finally(() => setRunning(false))
  }
  return <div className="research-lab"><div className="page-intro"><p className="eyebrow">PRODUCT RESEARCH PIPELINE</p><h1>Normalize and rank product candidates.</h1><p>Provide source-backed candidates or import them from an approved provider. AiBay will canonicalize URLs, deduplicate identity fingerprints, show missing evidence, and explain each score. It will not claim live demand from incomplete data.</p></div><Card className="research-input-card"><SectionHeading eyebrow="CANDIDATES" title="Evidence-bearing product rows" action={<button className="secondary-button" onClick={() => setRows((previous) => [...previous, { sourceUrl: '', title: '', brand: '', model: '', price: '' }])}>Add row</button>} /><div className="research-row-list">{rows.map((row, index) => <div className="research-row" key={index}><input aria-label={`Candidate ${index + 1} source URL`} placeholder="Source URL" value={row.sourceUrl} onChange={(event) => update(index, 'sourceUrl', event.target.value)} /><input aria-label={`Candidate ${index + 1} title`} placeholder="Product title" value={row.title} onChange={(event) => update(index, 'title', event.target.value)} /><input aria-label={`Candidate ${index + 1} brand`} placeholder="Brand" value={row.brand} onChange={(event) => update(index, 'brand', event.target.value)} /><input aria-label={`Candidate ${index + 1} model`} placeholder="Model / SKU" value={row.model} onChange={(event) => update(index, 'model', event.target.value)} /><input aria-label={`Candidate ${index + 1} price`} placeholder="Price" inputMode="decimal" value={row.price} onChange={(event) => update(index, 'price', event.target.value)} /></div>)}</div><button className="primary-button" onClick={run} disabled={running}>{running ? <LoaderCircle className="spin" size={16} /> : <Search size={16} />}{running ? 'Running pipeline' : 'Normalize and rank'}</button></Card>{result && <Card className="research-results-card"><SectionHeading eyebrow="RESEARCH OUTPUT" title="Evidence-aware ranking" action={<div className="research-export-actions"><button className="text-button" onClick={() => void exportResults('json')}>JSON</button><button className="text-button" onClick={() => void exportResults('csv')}>CSV</button><button className="text-button" onClick={() => void exportResults('markdown')}>Markdown</button><StatusPill state={result.status === 'completed' ? 'local' : 'warn'}>{result.status}</StatusPill></div>} /><p className="research-result-note">{result.note || `Removed ${result.duplicateCount || 0} duplicate candidate(s).`}</p><div className="research-result-list">{(result.candidates || []).map((candidate) => <div className="research-result-row" key={`${candidate.sourceUrl}-${candidate.title}`}><div><strong>{candidate.title}</strong><small>{candidate.sourceUrl}</small></div><StatusPill state="neutral">Score {candidate.score.total}</StatusPill><span>{candidate.validation.missing.length ? `${candidate.validation.missing.length} fields missing` : 'Evidence complete'}</span></div>)}</div></Card>}</div>
}

function EmptyProductState({ url, setUrl, onImport, notify }: { url: string; setUrl: (value: string) => void; onImport: () => void; notify: (message: string) => void }) {
  const [consent, setConsent] = useState(true)
  return <div className="empty-product-shell">
    <div className="hero-grid"><div className="hero-copy"><div className="eyebrow-row"><span className="signal-dot" /> EVIDENCE-BACKED LISTING RESEARCH</div><h1>Turn a product page into an eBay-ready decision.</h1><p>AiBay captures attributable product facts, separates variants, creates a reviewable listing draft, and keeps any market comparison clearly labelled by source. Nothing is published automatically.</p><div className="hero-trust-row"><span><ShieldCheck size={16} /> No CAPTCHA bypass</span><span><BadgeCheck size={16} /> Source provenance</span><span><Clock3 size={16} /> Timestamped market view</span></div></div><div className="hero-score-card"><div className="dial"><span>01</span></div><div><p className="eyebrow">WHAT YOU GET</p><strong>One product workspace</strong><p>Evidence, variants, market position, media review, and a listing draft in a single controlled flow.</p></div></div></div>
    <div className="local-capability-strip"><span className="local-orb"><Zap size={17} /></span><div><strong>Local workspace ready</strong><p>Evidence review, deterministic listing drafts, exports, and image review work immediately. Optional marketplace research is clearly separated from local comparison work.</p></div><StatusPill state="local">No account setup required</StatusPill></div>
    <Card className="import-card"><div className="import-card-top"><div><p className="eyebrow">NEW PRODUCT</p><h2>Import a product source</h2><p>Start with a public product, manufacturer, or marketplace URL you are permitted to use.</p></div><StatusPill state="secure"><LockKeyhole size={13} /> Bounded acquisition</StatusPill></div><div className="url-input-wrap"><Link2 size={19} /><input aria-label="Product source URL" value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com/products/your-product" onKeyDown={(event) => event.key === 'Enter' && onImport()} /><button className="text-button" onClick={() => setUrl('https://store.example.com/products/aerostep-trail-runner')}>Use example</button></div><div className="import-control-row"><label className="consent-control"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} /><span>I have the right to use this product information and any images I later enhance or export.</span></label><button className="primary-button" disabled={!url.trim() || !consent} onClick={onImport}><Search size={17} /> Inspect product</button></div><div className="source-rule-row"><Info size={15} /> AiBay uses approved APIs or public structured/visible data. Login, CAPTCHA, and blocked sources stop with a manual-evidence fallback.</div></Card>
    <CapabilityPanel notify={notify} /><div className="principle-grid"><Principle number="01" icon={<PackageSearch size={22} />} title="Extract with evidence" description="Every field carries its source, method, timestamp, and confidence—unknown remains unknown." /><Principle number="02" icon={<BarChart3 size={22} />} title="Compare the right market" description="Direct matches and broader comparables are labelled separately for eBay US." /><Principle number="03" icon={<Sparkles size={22} />} title="Review before export" description="Titles, claims, item specifics, strategy, and enhanced media are gated by human review." /></div>
  </div>
}
function Principle({ number, icon, title, description }: { number: string; icon: ReactNode; title: string; description: string }) { return <Card className="principle-card"><div className="principle-top"><span>{number}</span>{icon}</div><h3>{title}</h3><p>{description}</p></Card> }

function JobTimeline({ events, state }: { events: JobEvent[]; state: JobState }) {
  const completed = events.filter((event) => event.state === 'complete').length
  const active = events.some((event) => event.state === 'active')
  const progress = events.length ? Math.round(((completed + (active ? 0.45 : 0)) / events.length) * 100) : 0
  const stopped = state === 'blocked' || state === 'unavailable'
  const heading = state === 'optimizing' ? 'Building your listing package' : state === 'blocked' ? 'Source requires a safe fallback' : state === 'unavailable' ? 'Public product evidence was not recovered' : 'Inspecting product source'
  return <Card className="timeline-card"><div className="timeline-head"><div><p className="eyebrow">LIVE IMPORT PROGRESS</p><h3>{heading}</h3></div>{stopped ? <StatusPill state="warn"><AlertTriangle size={13} /> {state === 'blocked' ? 'Paused safely' : 'No source record'}</StatusPill> : <StatusPill state="live"><LoaderCircle className={state === 'ready' || state === 'complete' ? '' : 'spin'} size={13} /> {state === 'ready' || state === 'complete' ? 'Completed' : 'Working'}</StatusPill>}</div><div className="progress-track" role="progressbar" aria-label="Product import progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress}><span style={{ width: `${progress}%` }} /></div><p className="progress-copy">{completed} of {events.length} stages completed{active ? ' · current stage is in progress' : ''}.</p><div className="timeline-list">{events.map((event) => <div className={clsx('timeline-event', `timeline-${event.state}`)} key={event.id}><div className="timeline-mark">{event.state === 'complete' ? <Check size={14} /> : event.state === 'active' ? <LoaderCircle className="spin" size={14} /> : event.state === 'blocked' ? <AlertTriangle size={14} /> : <span />}</div><div><strong>{event.label}</strong><p>{event.detail}</p></div></div>)}</div></Card>
}
function ManualEvidenceForm({ sourceUrl, onCreate, onCancel }: { sourceUrl: string; onCreate: (input: { sourceUrl: string; title: string; brand: string; model: string; price: string; currency: string; description: string }) => void; onCancel: () => void }) {
  const [form, setForm] = useState({ title: '', brand: '', model: '', price: '', currency: 'USD', description: '' })
  const update = (key: keyof typeof form, value: string) => setForm((previous) => ({ ...previous, [key]: value }))
  return <Card className="manual-evidence-card"><SectionHeading eyebrow="CONTINUE PRODUCT RESEARCH" title="Create the exact-product handoff" /><p>AiBay stopped the protected source without substituting another item. If you can view the product in your own browser, paste only the title, brand, model, price, variants, or specifications you are entitled to use. These fields remain user-provided and review-gated.</p><p className="manual-evidence-source"><Link2 size={14} /> Exact source: <a href={sourceUrl} target="_blank" rel="noreferrer">{sourceUrl}</a></p><div className="manual-evidence-grid"><label>Product title<input value={form.title} onChange={(event) => update('title', event.target.value)} placeholder="Exact product title" /></label><label>Brand<input value={form.brand} onChange={(event) => update('brand', event.target.value)} placeholder="Brand or manufacturer" /></label><label>Model / part number<input value={form.model} onChange={(event) => update('model', event.target.value)} placeholder="Model, SKU, or part number" /></label><label>Source price<input inputMode="decimal" value={form.price} onChange={(event) => update('price', event.target.value)} placeholder="0.00" /></label><label>Currency<select value={form.currency} onChange={(event) => update('currency', event.target.value)}><option value="USD">USD</option><option value="EUR">EUR</option><option value="GBP">GBP</option><option value="CAD">CAD</option></select></label><label className="manual-evidence-wide">Description or specification notes<textarea value={form.description} onChange={(event) => update('description', event.target.value)} placeholder="Paste only facts supported by your product page, purchase record, manufacturer specification, or rights-cleared source material." rows={4} /></label></div><div className="manual-evidence-actions"><button className="primary-button" disabled={!form.title.trim()} onClick={() => onCreate({ sourceUrl, ...form })}><FileText size={16} /> Create reviewable record</button><button className="secondary-button" onClick={onCancel}>Use another source</button></div><p className="manual-evidence-note"><ShieldCheck size={14} /> You can add rights-cleared images in Media Studio after the record is created. Product claims remain review-gated until supporting evidence is reviewed.</p></Card>
}
function BlockedSource({ failure, events, state, onReset, onContinue }: { failure: ImportFailure; events: JobEvent[]; state: JobState; onReset: () => void; onContinue: (input: { sourceUrl: string; title: string; brand: string; model: string; price: string; currency: string; description: string }) => void }) {
  const diagnostic = failure.diagnostic
  const label = diagnostic?.status === 'session_required' ? 'SAFE RESEARCH HANDOFF' : diagnostic?.status === 'access_controlled' ? 'ACCESS-CONTROLLED SOURCE' : failure.blocked ? 'SAFE ACQUISITION STOP' : 'EVIDENCE HANDOFF'
  const title = diagnostic?.status === 'session_required' ? 'The exact source is protected — research can continue.' : failure.blocked ? 'The exact source stopped safely — research can continue.' : 'This exact source needs more evidence.'
  return <div className="blocked-source-wrap"><Card className="blocked-source-card"><div className="blocked-icon"><ShieldCheck size={28} /></div><p className="eyebrow">{label}</p><h1>{title}</h1><p>{failure.reason}</p><p className="blocked-source-subtitle">Nothing was replaced: no unrelated product, image set, fixture, or unverified market number was inserted.</p>{diagnostic && <div className="source-diagnostic"><div><span>Source route</span><strong>{diagnostic.adapter}</strong></div><div><span>Redirects inspected</span><strong>{diagnostic.redirectCount}</strong></div><div><span>Path</span><strong>{diagnostic.redirectHosts.join(' → ') || diagnostic.sourceHost}</strong></div></div>}<div className="fallback-list">{failure.alternatives.map((alternative) => <div key={alternative}><CheckCircle2 size={16} />{alternative}</div>)}</div><div className="blocked-source-actions"><a className="secondary-button" href={failure.sourceUrl} target="_blank" rel="noreferrer"><ExternalLink size={15} /> Open exact source</a><button className="secondary-button" onClick={onReset}><ChevronRight size={16} /> Use another source</button></div></Card><ManualEvidenceForm sourceUrl={failure.sourceUrl} onCreate={onContinue} onCancel={onReset} /><JobTimeline events={events} state={state} /></div>
}

function ProductOverview({ workspace, selectedVariant, setSelectedVariant, onOptimize, onOpenMedia, optimizing, optimization }: { workspace: ProductWorkspace; selectedVariant: string; setSelectedVariant: (id: string) => void; onOptimize: () => void; onOpenMedia: () => void; optimizing: boolean; optimization: OptimizationRun | null }) {
  const selected = workspace.variants.find((variant) => variant.id === selectedVariant) ?? workspace.variants[0]
  const [activeMediaId, setActiveMediaId] = useState(workspace.media[0]?.id)
  const primaryMedia = workspace.media.find((media) => media.id === activeMediaId) ?? workspace.media[0]
  const eligible = workspace.completeness >= 75 && !!selected
  return <><div className="workspace-header"><div className="breadcrumb"><span>Workspace</span><ChevronRight size={14} /><strong>{workspace.brand} · {workspace.model}</strong></div><div className="header-actions"><StatusPill state="secure"><ShieldCheck size={13} /> Evidence retained</StatusPill></div></div><div className="product-hero"><div className="product-hero-copy"><div className="eyebrow-row"><span className="signal-dot" /> IMPORT COMPLETE · {relativeTime(workspace.importedAt)}</div><h1>{workspace.title}</h1><p>{workspace.description}</p><div className="product-meta-row"><span><BadgeCheck size={16} /> {workspace.brand}</span><span><Tag size={16} /> {workspace.gtin}</span><span><Link2 size={16} /> {workspace.sourceHost}</span></div></div><div className="readiness-panel"><div className="readiness-ring"><strong>{workspace.completeness}</strong><span>%</span></div><div><p className="eyebrow">LISTING READINESS</p><strong>High-confidence product record</strong><p>{workspace.fields.filter((field) => field.state === 'needs_review' || field.state === 'unknown').length} fields need review before export.</p></div></div></div><div className="overview-grid"><Card className="product-card" noPadding><div className="product-media-main">{primaryMedia ? <img src={primaryMedia.url} alt={primaryMedia.alt} /> : <div className="no-media-state"><ImageIcon size={29} /><strong>No public source image</strong><span>Add rights-cleared media before export.</span></div>}{primaryMedia && <div className="media-source-label"><ImageIcon size={14} /> Source original</div>}</div>{workspace.media.length > 0 && <div className="media-thumb-row">{workspace.media.map((media) => <button onClick={() => setActiveMediaId(media.id)} aria-label={`View ${media.alt}`} className={clsx('media-thumb', media.id === primaryMedia?.id && 'active')} key={media.id}><img src={media.url} alt={media.alt} />{media.enhanced && <span><Sparkles size={11} /></span>}</button>)}</div>}<div className="product-card-foot"><span>{workspace.media.length ? 'Source asset set' : 'Manual media needed'}</span><button className="text-button" onClick={onOpenMedia}>Open media studio <ArrowUpRight size={14} /></button></div></Card><Card className="variants-card"><SectionHeading eyebrow="VARIATION CONTROL" title="Select a selling variation" action={<StatusPill state="neutral">{workspace.variants.length} active SKUs</StatusPill>} /><div className="selected-variant-summary"><div><span className="eyebrow">SELECTED</span><strong>{selected.label}</strong><small>{selected.sku}</small></div><div><span className="eyebrow">SOURCE PRICE</span><strong>{money(selected.price, workspace.currency)}</strong><small>{selected.stock} units shown</small></div></div><div className="variant-list">{workspace.variants.map((variant) => <button onClick={() => setSelectedVariant(variant.id)} className={clsx('variant-row', selectedVariant === variant.id && 'selected')} key={variant.id}><span className="variant-radio" /><span><strong>{variant.label}</strong><small>{variant.sku} · {variant.stock} shown</small></span><strong>{money(variant.price, workspace.currency)}</strong></button>)}</div><button className="optimize-button" disabled={!eligible || optimizing} onClick={onOptimize}>{optimizing ? <LoaderCircle className="spin" size={18} /> : <Sparkles size={18} />} {optimization ? 'Refresh optimized package' : 'Optimize item'}<span>{eligible ? 'Evidence ready' : 'Complete required fields'}</span></button><p className="hint-text"><ShieldCheck size={14} /> Creates a reviewable draft only. It never posts a listing or changes a marketplace account.</p></Card></div></>
}

function EvidencePanel({ fields }: { fields: EvidenceField[] }) { return <Card className="evidence-panel"><SectionHeading eyebrow="SOURCE INTEGRITY" title="Product evidence" /><div className="field-list">{fields.map((field) => <div className="field-row" key={field.label}><div><span>{field.label}</span><strong>{field.value}</strong><small>{field.method} · {field.source}</small></div><div className="field-right"><EvidenceBadge state={field.state} /><small>{field.confidence ? `${field.confidence}%` : '—'}</small></div></div>)}</div><div className="source-foot"><ShieldCheck size={15} /> Every field is retained with source method, timestamp, and confidence.</div></Card> }
type MarketMode = 'live' | 'unavailable'
const emptyMarket = (): MarketSnapshot => ({ id: 'market_empty', query: '', capturedAt: '', marketplace: 'EBAY_US', currency: 'USD', resultCount: 0, directMatchCount: 0, listings: [], commonTerms: [], itemSpecificGaps: [] })
function MarketPanel({ listings, capturedAt, onRefresh, mode }: { listings: MarketListing[]; capturedAt: string; onRefresh: () => void; mode: MarketMode }) { const prices = listings.map((listing) => listing.price + listing.shipping); const low = prices.length ? Math.min(...prices) : null; const high = prices.length ? Math.max(...prices) : null; const unavailable = mode !== 'live'; const label = mode === 'live' ? 'Live eBay snapshot' : 'No live market data yet'; return <Card className="market-panel"><SectionHeading eyebrow="MARKET COMPARISON" title="Comparison workspace" action={<button className="icon-text-button" onClick={onRefresh}><RefreshCw size={15} /> Refresh</button>} /><div className="market-status"><StatusPill state={mode === 'live' ? 'live' : 'warn'}><Info size={13} /> {label}</StatusPill><span>{unavailable ? 'Click Refresh to query current eBay listings in real time.' : `Live snapshot ${relativeTime(capturedAt)} · direct and comparable results separated`}</span></div><div className="market-range"><div><span className="eyebrow">DISPLAYED PRICE BAND</span><strong>{low === null || high === null ? 'No active listings returned' : `${money(low)} — ${money(high)}`}</strong><small>{unavailable ? 'No listings loaded yet — refresh to fetch live data.' : listings.length ? `${listings.length} live listings fetched just now` : 'Refine the query or check provider status.'}</small></div><div className="market-bars">{unavailable ? <span className="market-unavailable-mark"><Info size={18} /></span> : <><i style={{ height: '46%' }} /><i style={{ height: '72%' }} /><i style={{ height: '58%' }} /><i style={{ height: '86%' }} /><i style={{ height: '64%' }} /></>}</div></div>{!unavailable && <div className="listing-table">{listings.map((listing) => <div className="market-row" key={listing.id}><img src={listing.image} alt="Comparable eBay listing" /><div className="market-title"><div><StatusPill state={listing.matched === 'direct' ? 'live' : 'neutral'}>{listing.matched === 'direct' ? 'Direct' : 'Comparable'}</StatusPill><a href={listing.url} target="_blank" rel="noreferrer">{listing.title} <ExternalLink size={12} /></a></div><small>{listing.condition} · {listing.imageCount} images · {listing.seller} ({listing.feedback}%)</small></div><div className="market-price"><strong>{money(listing.price)}</strong><small>{listing.shipping ? `+ ${money(listing.shipping)} ship` : 'Free shipping shown'}</small></div></div>)}</div>}</Card> }
function MarketIntelligence({ onRefresh, snapshot, mode }: { onRefresh: () => void; snapshot: MarketSnapshot; mode: MarketMode }) { const unavailable = mode === 'unavailable'; return <div className="market-page-grid"><MarketPanel listings={snapshot.listings} capturedAt={snapshot.capturedAt} onRefresh={onRefresh} mode={mode} /><Card className="market-insight-card"><SectionHeading eyebrow="RESEARCH NOTES" title={unavailable ? 'Market research status' : 'Visible positioning opportunities'} />{unavailable ? <div className="market-empty-note"><Info size={18} /><p>No live market data has been loaded for this record yet. Refresh to query current eBay listings in real time (bounded public search; if eBay blocks the request, AiBay reports it and never substitutes fake data).</p></div> : <><div className="insight-block"><span className="mini-icon blue"><Search size={15} /></span><div><strong>Terms appearing in active results</strong><p>{snapshot.commonTerms.map((term) => <span className="keyword" key={term}>{term}</span>)}</p></div></div><div className="insight-block"><span className="mini-icon amber"><Tag size={15} /></span><div><strong>Likely item-specific coverage gaps</strong><p>{snapshot.itemSpecificGaps.join(' · ')}</p></div></div><div className="market-disclaimer"><Info size={15} /> Observed active listings are not sold-price data and do not guarantee placement or conversion.</div></>}</Card></div> }

